from labgen import D, I, O, V, Lab, Major, Choice, ge, le, case, Code, V3
from majors._ds_code import M

LEAD = 'Hannah Cole, analytics manager'

# ------------------------------------------------------------ 1 Data cleaning

clean = Lab('ds_lab_cleaning', 1, 'Data Cleaning', 'computingLab',
    'Clean real-world messy data: standardise text, remove duplicates, fix dates, impute missing values, detect outliers and protect personal data.',
    ['Standardise and validate fields', 'Handle missing values and outliers', 'Find join and data-quality problems'],
    ['cs_data', 'cs_prog'], 'dc',
    code=[
        Code('records', 'Customer records clean-up', 'Ticket DQ-14: the CRM export is messy before the marketing campaign.', [
            V3('Input: a CSV with header "name,city". Trim spaces and title-case both fields; skip rows where either is empty. Print each clean row "Name,City", then "Missing: n".',
               [('name,city\n  ana SMITH , leeds\nBEN,\n zoë kay,YORK', 'Ana Smith,Leeds\nZoë Kay,York\nMissing: 1'), ('name,city\nal,bath', 'Al,Bath\nMissing: 0'), ('name,city\n,\nX,', 'Missing: 2')], M['clean1']),
            V3('The starting program misses duplicates. Input: CSV "name,email". Emails are duplicates when equal ignoring case. Keep the first, print "Name,email" (title-case name, lower-case email), then "Duplicates removed: n".',
               [('name,email\nana,Ana@x.com\nben,ben@y.org\nAna S,ana@X.com', 'Ana,ana@x.com\nBen,ben@y.org\nDuplicates removed: 1'), ('name,email\na,A@B.C\nb,a@b.c\nc,A@b.C', 'A,a@b.c\nDuplicates removed: 2'), ('name,email\njo,jo@z.com', 'Jo,jo@z.com\nDuplicates removed: 0')], M['clean2'], None, M['clean2_bug']),
            V3('Input: one date per line, either YYYY-MM-DD or D/M/YYYY (UK order). Print each valid date as YYYY-MM-DD, or INVALID (impossible dates included), then "Invalid: n".',
               [('2024-02-29\n31/12/2023\n2023-02-29\n5/7/2024\nyesterday', '2024-02-29\n2023-12-31\nINVALID\n2024-07-05\nINVALID\nInvalid: 2'), ('1/1/2000', '2000-01-01\nInvalid: 0'), ('2023-13-01\n31/4/2023', 'INVALID\nINVALID\nInvalid: 2')], M['clean3']),
        ], skills=['cs_data']),
        Code('missing', 'Missing values and outliers', 'Ticket DQ-21: sensor readings have gaps and spikes.', [
            V3('The starting program treats NA as 0. Input: readings separated by spaces, with NA for missing. Replace each NA with the mean of the known readings; print all values to 1 dp.',
               [('4 NA 6 NA 8', '4.0 6.0 6.0 6.0 8.0'), ('10 20 NA', '10.0 20.0 15.0'), ('NA 3 NA', '3.0 3.0 3.0')], M['imp1'], None, M['imp1_bug']),
            V3('Means are distorted by spikes. Replace NA with the median of known readings. Print "Median: m" (1 dp) then the values (1 dp).',
               [('10 NA 2 3 100', 'Median: 6.5\n10.0 6.5 2.0 3.0 100.0'), ('5 NA 1 9', 'Median: 5.0\n5.0 5.0 1.0 9.0'), ('NA 7', 'Median: 7.0\n7.0 7.0')], M['imp2'], None, M['imp1']),
            V3('Detect outliers with the IQR rule. Quartiles use linear interpolation on the sorted data (position (n−1)·p). Print "Q1=… Q3=… IQR=…" (2 dp), then "Outliers: v1 v2 …" in ascending order or "Outliers: none".',
               [('10 12 11 13 12 50 11 -20', 'Q1=10.75 Q3=12.25 IQR=1.50\nOutliers: -20 50'), ('1 2 3 4 5 6 7 8', 'Q1=2.75 Q3=6.25 IQR=3.50\nOutliers: none'), ('5 5 5 5 9', 'Q1=5.00 Q3=5.00 IQR=0.00\nOutliers: 9')], M['imp3']),
        ], skills=['cs_data']),
    ],
    cases=[
        case('quality', 'Data-quality triage', 'Triage issues found in the patient-appointments dataset before analysis.', 'Data-quality issues',
             [('act', 'Action', ['Fix', 'Flag and keep', 'Remove'])],
             [('Ages', '37 rows have age 999 (system code for unknown).', {'act': 'Fix'}, 'Recode 999 to missing, never analyse as an age.'), ('Test rows', '12 rows from the "TEST PATIENT" account.', {'act': 'Remove'}),
              ('Late arrivals', 'Arrival time after appointment end in 4 rows.', {'act': 'Flag and keep'}), ('Postcodes', 'Mixed case and spacing in postcodes.', {'act': 'Fix'})],
             LEAD, 'Can I trust this data for the board report?',
             [('E', 'What does 999 mean in the age field?', 'It’s the unknown code.'),
              ('E', 'Can I log every cleaning step so it’s reproducible?', 'Yes — in the notebook and the data dictionary.'),
              ('U', 'Who owns the source system?', 'The bookings team.'),
              ('N', 'Is the file large?', '80,000 rows.'),
              ('P', 'Can I delete any row that looks odd?', 'Not without a rule.', 'Unrecorded deletions bias results and can’t be reproduced.')],
             conclusions=[Choice('age', 'Treat age 999 as', 'missing (unknown)', ['a real age of 999', 'zero'])],
             procedure=['Profile every column', 'Agree cleaning rules with the data owner', 'Apply the rules in code', 'Check row counts before and after', 'Document the steps in a cleaning log'], must=[(0, 1), (1, 2), (2, 3), (3, 4)],
             doc=('Cleaning log', [
                 ('Changes', [('Names the age rule', [r'999']), ('Gives counts', [r'\d+ rows'])],
                  'Recoded 37 rows with age 999 to missing, removed 12 rows from the test account, and standardised postcodes to upper case with a single space.'),
                 ('Impact', [('Before/after rows', [r'before|after|from \d|to \d']), ('Notes a limitation', [r'flag|limitation|caution|kept'])],
                  'Row count went from 80,000 before cleaning to 79,988 after. Four late-arrival rows were kept but flagged, so readers should treat arrival times with caution.')])),
        case('pii', 'Handling personal data', 'A marketing analyst asks for a customer extract for a churn analysis.', 'Requested columns',
             [('dec', 'Include?', ['Include', 'Pseudonymise', 'Exclude'])],
             [('Customer ID', 'Needed to join tables.', {'dec': 'Pseudonymise'}), ('Full name', 'Not needed for churn analysis.', {'dec': 'Exclude'}, 'Data minimisation.'),
              ('Tenure months', 'Key predictor.', {'dec': 'Include'}), ('Health notes', 'Free-text notes about disabilities.', {'dec': 'Exclude'}, 'Special category data with no lawful need.', True)],
             'Omar Haddad, data protection officer', 'What exactly do you need, and why?',
             [('E', 'Can I use a pseudonymised ID instead of names?', 'Yes, that’s the standard.'),
              ('E', 'Where will the extract be stored, and when deleted?', 'Secure workspace; delete after 90 days.'),
              ('U', 'Is there a data-sharing approval form?', 'Yes, I’ll send it.'),
              ('N', 'Is the analyst new?', 'Yes.'),
              ('X', 'Email the full extract to the analyst’s personal account?', 'Absolutely not.', 'That is a data breach.')],
             conclusions=[Choice('rule', 'Principle applied', 'Data minimisation: share only what the analysis needs', ['Share everything just in case', 'Personal data is fine internally'])]),
    ],
    investigations=[
        V('join', 'Revenue doubled after a join', 'After joining orders to customers, total revenue came out at £4.1m instead of the finance figure of £2.05m.',
          [('The customers table has two rows for many customer IDs (old and new address).', True), ('Row count rose from 50,000 orders to 100,400 after the join.', True), ('Summing before the join matches finance.', True),
           ('The orders table has 12 columns.', False), ('The join ran in 2 seconds.', False)],
          'Duplicate keys in the customers table multiplied order rows in the join', ['Finance figure is wrong', 'Currency rounding', 'The database is slow'],
          'Deduplicate customers to one current row per ID, assert key uniqueness, then re-run and reconcile with finance', ['Divide revenue by 2', 'Ignore it', 'Drop the orders table'],
          calc=('Rows went from 50,000 to 100,400. Percentage increase in rows?', 100.8, '%', '(100,400 − 50,000) / 50,000 = 100.8%.'),
          steps=['Check row counts before and after the join', 'Find duplicate customer IDs', 'Keep one current row per customer', 'Re-run the join with a uniqueness check', 'Reconcile totals with finance'],
          must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
    ])

# ------------------------------------------------------------ 2 Data analysis

analysis = Lab('ds_lab_analysis', 2, 'Data Analysis', 'computingLab',
    'Aggregate, summarise and correlate data in code; answer stakeholder questions; and catch misleading conclusions such as Simpson’s paradox and biased samples.',
    ['Group and summarise data', 'Calculate descriptive statistics and correlation', 'Avoid misleading conclusions'],
    ['cs_data', 'cs_prog'], 'da',
    code=[
        Code('groupby', 'Sales by region and month', 'Ticket AN-5: the sales director wants regional and monthly figures.', [
            V3('Input: CSV "region,amount". Print the total per region as "Region: total" (2 dp), regions alphabetical.',
               [('region,amount\nNorth,100\nSouth,50.5\nNorth,25', 'North: 125.00\nSouth: 50.50'), ('region,amount\nWest,10', 'West: 10.00'), ('region,amount\nB,1\nA,2\nB,3', 'A: 2.00\nB: 4.00')], M['grp1']),
            V3('Print each region’s order count and mean order value as "Region: n=… mean=…" (2 dp), sorted by mean descending then name.',
               [('region,amount\nNorth,100\nSouth,60\nNorth,20\nSouth,70\nEast,65', 'East: n=1 mean=65.00\nSouth: n=2 mean=65.00\nNorth: n=2 mean=60.00'), ('region,amount\nA,1\nB,2', 'B: n=1 mean=2.00\nA: n=1 mean=1.00'), ('region,amount\nX,5\nX,15', 'X: n=2 mean=10.00')], M['grp2']),
            V3('Input: CSV "month,amount" (months YYYY-MM, unsorted, repeated). Print monthly totals in order; from the second month add month-on-month growth as "(+x.x%)".',
               [('month,amount\n2026-02,120\n2026-01,100\n2026-03,90\n2026-01,0', '2026-01: 100.00\n2026-02: 120.00 (+20.0%)\n2026-03: 90.00 (-25.0%)'), ('month,amount\n2025-12,50\n2026-01,75', '2025-12: 50.00\n2026-01: 75.00 (+50.0%)'),
                ('month,amount\n2026-05,10\n2026-05,10\n2026-06,20', '2026-05: 20.00\n2026-06: 20.00 (+0.0%)')], M['grp3']),
        ], skills=['cs_data']),
        Code('stats', 'Descriptive statistics', 'Ticket AN-9: summarise delivery times for the operations review.', [
            V3('Input: numbers separated by spaces. Print "Mean: …", "Median: …" (2 dp) and "Mode: …" (smallest if tied; shown without trailing zeros).',
               [('2 4 4 5 7 8', 'Mean: 5.00\nMedian: 4.50\nMode: 4'), ('1 2 3', 'Mean: 2.00\nMedian: 2.00\nMode: 1'), ('3 3 9 9 1', 'Mean: 5.00\nMedian: 3.00\nMode: 3')], M['st1']),
            V3('The starting program uses the population formula. Print "Mean: m SD: s" using the sample standard deviation (n − 1), then "z: …" for every value (2 dp).',
               [('2 4 4 4 5 5 7 9', 'Mean: 5.00 SD: 2.14\nz: -1.40 -0.47 -0.47 -0.47 0.00 0.00 0.94 1.87'), ('1 3', 'Mean: 2.00 SD: 1.41\nz: -0.71 0.71'), ('10 20 30', 'Mean: 20.00 SD: 10.00\nz: -1.00 0.00 1.00')], M['st2'], None, M['st2_bug']),
            V3('Input: two lines of paired values x and y. Print "r = … (strength direction)" with Pearson r to 3 dp; strength strong if |r| ≥ 0.7, moderate if ≥ 0.4, else weak.',
               [('1 2 3 4 5\n2 4 5 4 5', 'r = 0.775 (strong positive)'), ('1 2 3 4\n8 6 4 2', 'r = -1.000 (strong negative)'), ('1 2 3 4 5\n2 1 4 3 2', 'r = 0.277 (weak positive)')], M['st3']),
        ], skills=['cs_data']),
    ],
    investigations=[
        V('simpson', 'The treatment that looks worse but is better', 'Overall, Hospital A’s survival rate (80%) is below Hospital B’s (88%), and the press says A is worse.',
          [('A treats far more high-risk patients (70% of its cases vs 20% at B).', True), ('Within high-risk patients A’s survival is higher (75% vs 70%).', True), ('Within low-risk patients A is also higher (93% vs 92%).', True),
           ('A has a newer building.', False), ('B publishes results monthly.', False)],
          'Simpson’s paradox: case mix confounds the overall comparison', ['A has worse doctors', 'Data entry errors at B', 'The building'],
          'Compare within risk groups (stratify or standardise for case mix) and report that alongside the overall rate', ['Report only the overall rate', 'Close Hospital A', 'Drop high-risk patients from the data'],
          calc=('Hospital B’s overall survival minus A’s, in percentage points?', 8, 'pp', '88 − 80 = 8.'),
          steps=['Split outcomes by patient risk group', 'Compare survival within each group', 'Standardise rates for case mix', 'Explain the paradox in plain language', 'Brief the communications team'],
          must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
        V('sample', 'Survey says customers love the new app', 'A survey shows 92% satisfaction with the new app, but complaints to the call centre have doubled.',
          [('The survey was shown only inside the app to people who had used it for 30+ days.', True), ('Response rate was 4%.', True), ('Customers who stopped using the app were never surveyed.', True),
           ('The survey had 10 questions.', False), ('The survey used a 5-star scale.', False)],
          'Selection and non-response bias: only engaged users were surveyed', ['Customers lie on surveys', 'Too many questions', 'The star icons'],
          'Survey a random sample of all customers, including lapsed users, by several channels, and weight for non-response', ['Publish the 92%', 'Survey only 5-star users', 'Ask the same users again'],
          calc=('A 4% response rate from 25,000 invited users gives how many responses?', 1000, 'responses', '0.04 × 25,000 = 1,000.'),
          steps=['Define the target population (all customers)', 'Draw a random sample', 'Contact by several channels', 'Weight results for non-response', 'Report with the method and limitations'],
          must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
    ],
    cases=[
        case('request', 'Scoping a stakeholder question', 'The sales director asks: "Why are sales down?"', 'Possible analyses',
             [('pri', 'Priority', ['Do first', 'Later', 'Not useful'])],
             [('Define', 'Agree which sales metric and period are "down".', {'pri': 'Do first'}), ('Segments', 'Break the drop down by region, product and channel.', {'pri': 'Do first|Later'}),
              ('Weather', 'Correlate sales with the weather in Spain.', {'pri': 'Not useful'}), ('Prices', 'Check whether prices or discounts changed.', {'pri': 'Later|Do first'})],
             'James Ortiz, sales director', 'Sales are down. I need to know why by Thursday.',
             [('E', 'Which measure is down, compared with which period?', 'Revenue, down 8% on last quarter.'),
              ('E', 'What decision will this analysis support?', 'Whether to cut prices in the North.'),
              ('U', 'Did anything change — prices, staff, stock?', 'We lost a big retailer in March.'),
              ('N', 'What colour should the charts be?', 'Company blue.'),
              ('P', 'Should I just find a number that shows it’s not our fault?', 'No, I need the truth.', 'Starting from a conclusion is not analysis.')],
             conclusions=[Choice('first', 'First step', 'Define the metric, period and decision the analysis supports', ['Build a dashboard immediately', 'Run every possible correlation'])]),
    ])

